use darling::{FromDeriveInput, FromVariant, ast::Fields};
use proc_macro2::{Span, TokenStream};
use quote::quote;
use syn::{Ident, PathSegment, punctuated::Punctuated};

use crate::{
    can::{
        self, CanVariantTupleWithIdAndType, decode::CAN_DECODE_MESSAGE_META_IDENT,
        encode::CAN_ENCODE_MESSAGE_META_IDENT,
    },
    message::MESSAGE_META_TYPES_IDENT,
};

/// Name of the module generated by the [`CanMessage`] macro which contains the
/// CAN id's for the different message enum variants
pub const CAN_MESSAGE_META_CAN_IDS_IDENT: &str = "__message_meta_can_ids";

#[derive(FromVariant)]
#[darling(attributes(can))]
pub struct CanMessageVariant {
    /// Unique id of the CAN message variant
    ///
    /// **Important**: Only variants which have a `#[can(id = ...)]` attribute are considered by this macro
    #[darling(default)]
    id: Option<u16>,

    ident: Ident,
    fields: Fields<syn::Field>,
}

#[derive(FromDeriveInput)]
#[darling(supports(enum_any))]
pub struct CanMessage {
    ident: Ident,
    data: darling::ast::Data<CanMessageVariant, ()>,
}

pub fn handle(can_message: CanMessage) -> TokenStream {
    let variants = can_message
        .data
        .take_enum()
        .unwrap_or_default()
        .into_iter()
        .filter(|variant| variant.id.is_some())
        .collect::<Vec<_>>();
    let ident = can_message.ident;

    let meta_types_mod = Ident::new(MESSAGE_META_TYPES_IDENT, Span::call_site());
    let meta_can_ids_mod = Ident::new(CAN_MESSAGE_META_CAN_IDS_IDENT, Span::call_site());
    let meta_can_decode_mod = Ident::new(CAN_DECODE_MESSAGE_META_IDENT, Span::call_site());
    let meta_can_encode_mod = Ident::new(CAN_ENCODE_MESSAGE_META_IDENT, Span::call_site());

    let can_ids = generate_meta_can_ids(&ident, &variants);
    let can_decode =
        generate_can_decode_impl(&ident, &variants, &meta_can_ids_mod, &meta_types_mod);
    let can_encode =
        generate_can_encode_impl(&ident, &variants, &meta_can_ids_mod, &meta_types_mod);

    quote! {
        #[allow(non_upper_case_globals)]
        /// generated by [`data_macros::CanMessage`] macro
        pub mod #meta_can_ids_mod {
            use super::#ident;
            use ::data_core::can_hal::StandardId;

            #can_ids
        }

        /// generated by [`data_macros::CanMessage`] macro
        pub mod #meta_can_decode_mod {
            use super::{#ident, #meta_can_ids_mod};
            use ::data_core::can_hal::{StandardId, CanDecode, codec};

            #can_decode
        }

        /// generated by [`data_macros::CanMessage`] macro
        pub mod #meta_can_encode_mod {
            use super::{#ident, #meta_can_ids_mod};
            use ::data_core::can_hal::{StandardId, CanEncode, codec};

            #can_encode
        }
    }
}

/// Generate the mapping from every CAN message variant to a [`can_hal::StandardId`]
fn generate_meta_can_ids(ident: &Ident, variants: &[CanMessageVariant]) -> TokenStream {
    let (idents, ids) = variants
        .iter()
        .map(|variant| (&variant.ident, variant.id))
        .collect::<(Vec<_>, Vec<_>)>();

    let length = idents.len();

    quote! {
        #(pub const #idents: StandardId = StandardId::new(#ids).expect("must be in range of a 11-bit integer");)*

        pub const ALL_IDS: [StandardId; #length] = [
            #(#idents),*
        ];

        impl #ident {
            /// All CAN id's used by variants of this message enum
            pub const ALL_CAN_IDS: [StandardId; #length] = ALL_IDS;
        }
    }
}

/// Generate the [`can_hal::Decode`] implementation for the message enum
fn generate_can_decode_impl(
    ident: &Ident,
    variants: &[CanMessageVariant],
    ids_mod_ident: &Ident,
    types_mod_ident: &Ident,
) -> TokenStream {
    let variant_paths = variants
        .iter()
        .map(|variant| {
            let mut type_path_segments = Punctuated::new();
            type_path_segments.push(PathSegment::from(types_mod_ident.clone()));
            type_path_segments.push_punct(syn::token::PathSep::default());
            type_path_segments.push(PathSegment::from(variant.ident.clone()));
            let variant_type_path = syn::Path {
                leading_colon: None,
                segments: type_path_segments,
            };

            let mut id_path_segments = Punctuated::new();
            id_path_segments.push(PathSegment::from(ids_mod_ident.clone()));
            id_path_segments.push_punct(syn::token::PathSep::default());
            id_path_segments.push(PathSegment::from(variant.ident.clone()));
            let variant_id_path = syn::Path {
                leading_colon: None,
                segments: id_path_segments,
            };

            (variant_type_path, variant_id_path)
        })
        .collect::<Vec<_>>();

    let variants = variants
        .iter()
        .zip(variant_paths.iter())
        .map(|(variant, (type_path, id_path))| {
            (&variant.ident, id_path, type_path, &variant.fields)
        })
        .collect::<Vec<CanVariantTupleWithIdAndType>>();

    can::decode::generate_can_decode_impl(ident, &variants)
}

/// Generate the [`can_hal::Encode`] implementation for the message enum
fn generate_can_encode_impl(
    ident: &Ident,
    variants: &[CanMessageVariant],
    ids_mod_ident: &Ident,
    types_mod_ident: &Ident,
) -> TokenStream {
    let variant_paths = variants
        .iter()
        .map(|variant| {
            let mut type_path_segments = Punctuated::new();
            type_path_segments.push(PathSegment::from(types_mod_ident.clone()));
            type_path_segments.push_punct(syn::token::PathSep::default());
            type_path_segments.push(PathSegment::from(variant.ident.clone()));
            let variant_type_path = syn::Path {
                leading_colon: None,
                segments: type_path_segments,
            };

            let mut id_path_segments = Punctuated::new();
            id_path_segments.push(PathSegment::from(ids_mod_ident.clone()));
            id_path_segments.push_punct(syn::token::PathSep::default());
            id_path_segments.push(PathSegment::from(variant.ident.clone()));
            let variant_id_path = syn::Path {
                leading_colon: None,
                segments: id_path_segments,
            };

            (variant_type_path, variant_id_path)
        })
        .collect::<Vec<_>>();

    let variants = variants
        .iter()
        .zip(variant_paths.iter())
        .map(|(variant, (type_path, id_path))| {
            (&variant.ident, id_path, type_path, &variant.fields)
        })
        .collect::<Vec<CanVariantTupleWithIdAndType>>();

    can::encode::generate_can_encode_impl(ident, &variants)
}
